const CONFIG = $('Live Polling Configuration').first().json.config;
// Best effort only: static data is not an atomic lock across executions.
// Mark completion after successful API calls, never before attempting delivery.
const state = $getWorkflowStaticData('global');
state.processedComments ??= {};
const now = Date.now();
for (const [id, time] of Object.entries(state.processedComments)) {
  if (now - time > 86400000) delete state.processedComments[id];
}
const seen = new Set();
const output = [];
const normalize = value => String(value).normalize('NFKD').replace(/\p{M}/gu, '').toUpperCase();
const escapeRegex = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const add = (json, item) => output.push({ json, pairedItem: { item } });
for (const [index, input] of $input.all().entries()) {
  const body = input.json.body ?? input.json;
  if (body.object !== 'instagram') {
    add({ matched: false, reason: 'not_instagram' }, index);
    continue;
  }
  for (const entry of Array.isArray(body.entry) ? body.entry : []) {
    if (String(entry.id) !== CONFIG.instagramAccountId) {
      add({ matched: false, reason: 'account_not_targeted' }, index);
      continue;
    }
    const changes = Array.isArray(entry.changes) ? entry.changes
      : (entry.field && entry.value ? [{ field: entry.field, value: entry.value }] : []);
    for (const change of changes) {
      const ignore = reason => add({ matched: false, reason }, index);
      if (change.field !== 'comments') { ignore('not_a_comment_field'); continue; }
      const value = change.value || {};
      // Facebook/Unified and Instagram Login notifications can use different keys.
      const commentId = String(value.id || value.comment_id || '');
      const commentText = String(value.text || '').trim();
      const fromId = String(value.from?.id || '');
      const cleanUsername = String(value.from?.username || 'anonymous').replace(/^@/, '');
      const mediaId = String(value.media?.id || '');
      if (!commentId || !commentText) { ignore('missing_comment_data'); continue; }
      if (CONFIG.targetMediaId && mediaId !== CONFIG.targetMediaId) { ignore('media_id_not_targeted'); continue; }
      if (fromId === CONFIG.instagramAccountId || cleanUsername.toLowerCase() === CONFIG.instagramUsername.toLowerCase()) {
        ignore('self_bot_comment_ignored'); continue;
      }
      if (state.processedComments[commentId] || seen.has(commentId)) { ignore('duplicate_comment'); continue; }
      seen.add(commentId);
      const text = normalize(commentText);
      const matchedKeyword = CONFIG.triggerKeywords.find(keyword =>
        new RegExp(`(^|[^\\p{L}\\p{N}_])${escapeRegex(normalize(keyword))}($|[^\\p{L}\\p{N}_])`, 'u').test(text));
      if (!matchedKeyword) { ignore('keyword_not_matched'); continue; }
      add({
        matched: true, commentId, commentText, fromId, cleanUsername,
        username: '@' + cleanUsername, mediaId, matchedKeyword,
        publicReplyText: 'Thanks for your interest! We will send the details by DM.',
        dmText: `Hey @${cleanUsername}! 👋 Thanks for checking out ${CONFIG.startupName}.\n\nYou commented "${matchedKeyword}" — here is your direct access link:\n👉 ${CONFIG.startupLink}\n\nLet us know if you have any questions!`,
        timestamp: new Date(now).toISOString(),
        spreadsheetId: CONFIG.spreadsheetId, sheetName: CONFIG.sheetName,
        chatId: CONFIG.telegramChatId, config: CONFIG,
      }, index);
    }
  }
}
return output.length ? output : [{ json: { matched: false, reason: 'no_comment_events' }, pairedItem: { item: 0 } }];

// Run once per comment item — keeps batched comments separate.
const meta = $('Filter & Parse Comment Event').item.json;
const dmResult    = $('Send Personalized Instagram DM').item.json;
const replyResult = $('Post Public Comment Reply').item.json;
const dm    = dmResult.body    ?? dmResult;
const reply = replyResult.body ?? replyResult;
const dmAccepted    = !dm.error    && Boolean(dm.message_id);
const replyAccepted = !reply.error && Boolean(reply.id);
const errorText = r => String(r.error?.message || r.error || 'No success ID returned').slice(0, 200);
const dmStatus     = dmAccepted    ? '✅ Accepted by Meta' : '❌ Failed: ' + errorText(dm);
const publicStatus = replyAccepted ? '✅ Accepted by Meta' : '❌ Failed: ' + errorText(reply);

const escapeHtml = v => String(v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const telegramText = [
  '🚀 <b>New Instagram Lead!</b>',
  '━━━━━━━━━━━━━━━━━━━━━━━━',
  '',
  '👤 <b>User</b>',
  '   <a href="https://instagram.com/' + escapeHtml(meta.cleanUsername) + '">@' + escapeHtml(meta.cleanUsername) + '</a>',
  '',
  '💬 <b>Comment</b>',
  '   "<i>' + escapeHtml(meta.commentText) + '</i>"',
  '',
  '🎯 <b>Triggered by keyword:</b> <code>' + escapeHtml(meta.matchedKeyword) + '</code>',
  '',
  '━━━━━━━━━━━━━━━━━━━━━━━━',
  '',
  '📣 <b>Public Reply</b>',
  '   ' + escapeHtml(publicStatus),
  '',
  '📩 <b>Direct Message</b>',
  '   ' + escapeHtml(dmStatus),
  '',
  '━━━━━━━━━━━━━━━━━━━━━━━━',
  '',
  '🕐 <b>Time:</b> ' + escapeHtml(meta.timestamp || new Date().toISOString()),
  '📊 <a href="https://docs.google.com/spreadsheets/d/' + meta.spreadsheetId + '/edit">Open Leads Sheet ↗</a>',
].join('\n');

return { json: {
  spreadsheetId:        meta.spreadsheetId,
  sheetName:            meta.sheetName,
  chatId:               meta.chatId,
  telegramText,
  Timestamp:            meta.timestamp,
  'Instagram Username': meta.username,
  'User ID':            meta.fromId,
  'Trigger Keyword':    meta.matchedKeyword,
  'Comment Text':       meta.commentText,
  'Media ID':           meta.mediaId,
  'Comment ID':         meta.commentId,
  'Public Reply':       publicStatus,
  'DM Status':          dmStatus,
  'Lead Status':        dmAccepted ? 'New Lead' : 'Needs Retry',
} };

const config = $('Live Polling Configuration').first().json.config;
const response = $input.first().json;
if (!Array.isArray(response.data)) {
  throw new Error('Meta did not return a media list. Check the read request and token permissions.');
}
return response.data
  .filter(media => media.id && media.comments_count !== 0)
  .filter(media => !config.targetMediaId || String(media.id) === String(config.targetMediaId))
  .slice(0, config.polling.mediaLimit)
  .map(media => ({ json: {
    mediaId: String(media.id),
    mediaUrl: String(media.permalink || ''),
    moreMediaAvailable: Boolean(response.paging?.next),
  }, pairedItem: { item: 0 } }));

const config = $('Live Polling Configuration').first().json.config;
const media = $('Select Media to Check').item.json;
if (!Array.isArray($json.data)) throw new Error('Meta did not return a comments list');
const lookbackMs = (config.polling?.lookbackMinutes || 1440) * 60000;
const cutoff = Date.now() - lookbackMs;
const changes = [];
for (const comment of $json.data) {
  const createdAt = Date.parse(comment.timestamp);
  if (!Number.isFinite(createdAt) || createdAt < cutoff || createdAt > Date.now() + 300000) continue;
  changes.push({
    field: 'comments',
    value: {
      id: String(comment.id || ''),
      text: String(comment.text || ''),
      timestamp: comment.timestamp,
      from: {
        id: String(comment.from?.id || ''),
        username: String(comment.from?.username || comment.username || 'anonymous')
      },
      media: { id: media.mediaId },
    }
  });
}
return {
  json: {
    body: { object: 'instagram', entry: [{ id: config.instagramAccountId, changes }] },
    polling: {
      mediaId: media.mediaId,
      mediaUrl: media.mediaUrl,
      commentsReturned: $json.data.length,
      moreCommentsAvailable: Boolean($json.paging?.next)
    },
  }
};
